using MediatR;using ProjectNet.Application.Abstractions;using ProjectNet.Application.DTOs;using ProjectNet.Domain.Common;namespace ProjectNet.Application.Queries.GetCustomerById;public sealed class GetCustomerByIdQueryHandler : IRequestHandler<GetCustomerByIdQuery, CustomerDto?> { private readonly ICustomerRepository _r; public GetCustomerByIdQueryHandler(ICustomerRepository r)=>_r=r; public async Task<CustomerDto?> Handle(GetCustomerByIdQuery request, CancellationToken ct){ var c=await _r.GetByIdAsync(request.Id,ct); return c?.ToDto(); } }
